input.command:
cd /tmp/probe/comments/in && cat > 03_ownline.go <<'EOF'
package testdata

import (
	// leading comment above first import
	"fmt"
	// floating comment between
	"log"

	// comment above os
	"os"
	// trailing comment at end of block
)
EOF
/tmp/probe/comments/t.sh "03 own-line comments" /tmp/probe/comments/in/03_ownline.go

cd /tmp/probe/comments/in && cat > 04_doc.go <<'EOF'
package testdata

// doc comment above import decl
import ( // same line as import (
	"fmt"
	"log"
) // same line as close paren

func f() {}
EOF
/tmp/probe/comments/t.sh "04 doc/paren comments" /tmp/probe/comments/in/04_doc.go; echo; /tmp/probe/comments/t.sh "04 doc/paren -format" /tmp/probe/comments/in/04_doc.go -format

cd /tmp/probe/comments/in && printf 'package testdata

import (
	"os" // c
	"fmt" // d
	"log"
)
' > 07a.go && printf 'package testdata

import (
	"os" // c
	"fmt" //	d
	"log"
)
' > 07b.go && /tmp/probe/comments/t.sh "07a no tabs" /tmp/probe/comments/in/07a.go; /tmp/probe/comments/t.sh "07b tab in comment" /tmp/probe/comments/in/07b.go

cd /tmp/probe/comments/in && printf 'package testdata

import (
	"fmt" // x
)
' > 15a.go && printf 'package testdata

import (
	"fmt"
)
' > 15b.go && printf 'package testdata

import (
	"fmt" // x
	"log"
)
' > 15c.go && for f in 15a 15b 15c; do /tmp/probe/comments/t.sh "$f" /tmp/probe/comments/in/$f.go; echo; done

cd /tmp/probe/comments/in && printf 'package testdata

import (
	"os" // c
	"fmt" //	d
)
' > 16a.go && printf 'package testdata

import (
	"os" // c
	"fmt" // d
)
' > 16b.go && printf 'package testdata

import (
	"os" /*a*/ // c
	"fmt" /*bb*/ // d
)
' > 16c.go && for f in 16a 16b 16c; do /tmp/probe/comments/t.sh "$f" /tmp/probe/comments/in/$f.go; echo; done

